<script>
const banner = document.querySelector('[banner-image="1"]');

gsap.set(banner, {
  scale: 1.3,
  skewX: -3,
  skewY: -2,
  transformPerspective: 2000,
  transformOrigin: "50% 50%"
});

gsap.to(banner, {
  scale: 1.1,
  skewX: 0,
  skewY: 0,
  transformPerspective: 2000,
  duration: 2.5,
  delay: 0,
  ease: "power2.out"
});
</script>
